// Focused final cases use normal app actions, actual fixture host RPCs and real
// native callbacks. No direct domain/database state or successful reply injection.
#[test]fn lc1_network_fresh_intent_mailbox_requires_current_marker_and_context(){
 use nt2_desktop_g0::world_local::Marker;
 let marker=Marker{kind:"nt2-world".into(),version:1,local_world:uuid::Uuid::new_v4(),bundle_digest:"a".repeat(64),actual_seed:"424242".into(),loot:"shared:0:424242".into()};
 for intent in [3u32,5]{for expired in [false,true]{for fault in 0..5{
  let mut mailbox=crate::pipe::rejoin::Mailbox::default();let contact=crate::pipe::rejoin::Contact{pid:nt2_local_ws::owner::Id::OsProcess(77),context:[2;16],association:*marker.local_world.as_bytes(),actual:424242};mailbox.admitted=Some(contact);mailbox.metadata=Some((nt2_local_ws::owner::Id::OsProcess(77),[2;16],marker.encode().unwrap()));mailbox.world_offered=Some((nt2_local_ws::owner::Id::OsProcess(77),marker.clone()));mailbox.world_context=Some([2;16]);mailbox.lookup=intent;mailbox.offline=intent==5;mailbox.terminal=intent==3;
  let mut pending=handoff::new(424242,"run".into(),1);pending.owner=Some((nt2_local_ws::owner::Id::OsProcess(77),[2;16]));pending.authority_until=if expired{Instant::now()}else{Instant::now()+Duration::from_secs(6)};
  let mut offered=marker.clone();if fault==1{offered.local_world=uuid::Uuid::new_v4()}let mut body=offered.encode().unwrap();if fault==4{body=b"{}".to_vec()}
  let mut request=vec![0;32];request[..4].copy_from_slice(&handoff::MAGIC.to_le_bytes());request[4..8].copy_from_slice(&8u32.to_le_bytes());request[8..12].copy_from_slice(&14u32.to_le_bytes());request[12..16].copy_from_slice(&(body.len() as u32).to_le_bytes());request[16..32].fill(if fault==2{1}else{2});request.extend(body);
  let reply=mailbox.transition(&Some(pending),if fault==3{nt2_local_ws::owner::Id::OsProcess(78)}else{nt2_local_ws::owner::Id::OsProcess(77)},&request);let result=u32::from_le_bytes(reply[12..16].try_into().unwrap());if fault==0{assert_eq!(result,intent);assert_eq!(mailbox.world_context,Some([2;16]));assert!(mailbox.admitted.is_some());}else{assert!(!matches!(result,3|5),"Wrong world/context/PID/malformed selector inherited terminal/offline intent, fault{fault} expired{expired}");}
 }}}
}
fn final_tail_terminal(v:&Value,world:&Value,context:&Value)->bool{
 v["connection"]["state"]=="Ended"&&v["fixture_current"]["stage"]=="Ended"&&v["lc1_lifecycle"]["record_world"]==*world&&v["lc1_lifecycle"]["record_intent"]=="Terminal"&&v["fixture_current"]["pending_release"]!=true&&v["g3"]["live_transport"]["grant_active"]==false&&v["fixture_terminal_native_fresh"]==true&&v["fixture_current"]["native"]["native_lookup"]==3&&v["fixture_current"]["native"]["native_lookup_world"]==*world&&v["fixture_current"]["native"]["native_lookup_context"]==*context&&v["fixture_current"]["native"]["native_owned_hold"]==true&&v["fixture_current"]["native"]["native_hold_marker"]==true&&v["fixture_current"]["native"]["native_hold_effect"]==true&&v["fixture_current"]["native"]["frame"].as_u64().zip(v["fixture_current"]["native"]["native_lookup_frame"].as_u64()).is_some_and(|(frame,status)|frame>=status&&frame-status<=1)&&v["fixture_current"]["native"]["protected"]==true&&v["fixture_current"]["native"]["native_context"]==*context
}
async fn final_tail_snapshot(client:&Client,native:&Native)->Value{
 let evidence=native_evidence(native);client.handle.command(move|c|Box::pin(async move{let fresh=evidence.modified.is_some_and(|at|at.elapsed().is_ok_and(|age|age<Duration::from_millis(500)));let mut snapshot=core_current_snapshot(c,Some(evidence));snapshot["fixture_terminal_native_fresh"]=json!(fresh);Ok(snapshot)})).await.unwrap()
}
async fn final_tail_durable_terminal(client:&Client,world:&Value)->bool{
 let scope=client.handle.command(|c|Box::pin(async move{Ok(c.world.record.as_ref().map(|r|json!({"identity":r.identity,"world":r.world})).unwrap_or(Value::Null))})).await.unwrap();if scope["world"]!=*world{return false}let store=client.world_files.clone();tokio::task::spawn_blocking(move||{let identity=serde_json::from_value(scope["identity"].clone()).unwrap();let world=serde_json::from_value(scope["world"].clone()).unwrap();nt2_desktop_g0::world_local::load(&*store,&identity,world).unwrap().is_some_and(|r|r.intent==nt2_desktop_g0::world_local::Intent::Terminal)}).await.unwrap()
}
async fn final_tail_wait_terminal(service:&mut Service,client:&Client,native:&Native,world:&Value,context:&Value)->Value{
 let until=Instant::now()+Duration::from_secs(20);loop{service.wall_clock();let snapshot=final_tail_snapshot(client,native).await;if final_tail_terminal(&snapshot,world,context)&&final_tail_durable_terminal(client,world).await{write_current(client,"exact new-world durable terminal with actual protection",&snapshot);return snapshot}assert!(Instant::now()<until,"Final tail terminal20s deadline: {snapshot}");tokio::time::sleep(Duration::from_millis(250)).await;}
}
async fn final_moderation_tail(service:&mut Service,consumer:&Client,peer:&Client,running:&mut Native,sam:&mut Native,stable:&Value,root:&std::path::Path){
 for terminal in ["ban","excluded"]{
  service.command(json!({"op":"nextRun"}));let current=service.private();let room=current["room"]["roomId"].as_str().unwrap().to_owned();join_current(consumer,room.clone()).await;join_current(peer,room).await;
  let consumer_bundle=bundle(service,consumer).await;let peer_bundle=bundle(service,peer).await;*running=Native::start(consumer,None,false);*sam=Native::start(peer,None,false);ready_owner(service,consumer,running,&consumer_bundle.0,false).await;ready_owner(service,peer,sam,&peer_bundle.0,false).await;
  let before=[current_snapshot(consumer,Some(running)).await,current_snapshot(peer,Some(sam)).await];for(i,(native,world))in[( &*running,&consumer_bundle.0),(&*sam,&peer_bundle.0)].into_iter().enumerate(){assert_eq!(before[i]["fixture_current"]["held"],true);assert_eq!(before[i]["fixture_current"]["native_held"],true);assert_eq!(before[i]["fixture_current"]["identity"]["world"],*world);assert_eq!(before[i]["g3"]["live_transport"]["grant_active"],false,"New run inherited movement authority");assert!(!native.root.join("playing").exists(),"New run inherited old Start");}assert_ne!(consumer_bundle.0,*stable);assert!(server_world(service,&consumer_bundle.0)["terminal_reason"].is_null());
  let context=before[0]["fixture_current"]["identity"]["context"].clone();
  if terminal=="ban"{service.command(json!({"op":"moderate","target":"consumer","action":"ban"}));}else{std::fs::write(sam.root.join("start"),b"selected peer Start").unwrap();service.command(json!({"op":"start","selectedWorldIds":[peer_bundle.0],"excludedDesktopIds":[before[0]["desktop_id"]]}));}
  final_tail_wait_terminal(service,consumer,running,&consumer_bundle.0,&context).await;assert!(!running.root.join("playing").exists());let canonical=server_world(service,&consumer_bundle.0);assert!(canonical["terminal_reason"].is_string());
  if terminal=="excluded"{ready_owner(service,peer,sam,&peer_bundle.0,true).await;let selected=current_snapshot(peer,Some(sam)).await;assert_eq!(selected["fixture_current"]["playing"],true);assert_eq!(selected["fixture_current"]["native_controls"],true);assert_eq!(selected["fixture_current"]["identity"]["world"],peer_bundle.0);final_tail_wait_terminal(service,consumer,running,&consumer_bundle.0,&context).await;assert!(!running.root.join("playing").exists());}
  if terminal=="ban"{service.command(json!({"op":"moderate","target":"consumer","action":"unban"}));elapsed(service,3).await;let after=final_tail_snapshot(consumer,running).await;assert!(final_tail_terminal(&after,&consumer_bundle.0,&context),"Unban revived a terminal world: {after}");assert_eq!(server_world(service,&consumer_bundle.0)["terminal_reason"],canonical["terminal_reason"]);assert!(!running.root.join("playing").exists(),"Unban briefly released terminal Controls");assert!(final_tail_durable_terminal(consumer,&consumer_bundle.0).await,"Unban revived protected terminal intent");}
  let terminal_state=final_tail_snapshot(consumer,running).await;std::fs::write(root.join(format!("tail-case-{terminal}.json")),serde_json::to_vec_pretty(&json!({"terminal":terminal,"consumerWorld":consumer_bundle.0,"peerWorld":peer_bundle.0,"before":before,"after":terminal_state,"canonical":server_world(service,&consumer_bundle.0),"durableTerminal":final_tail_durable_terminal(consumer,&consumer_bundle.0).await,"neverPlayed":!running.root.join("playing").exists(),"selectedPeer":current_snapshot(peer,Some(sam)).await})).unwrap()).unwrap();let mut selected_end=if terminal=="excluded"{let loss=expect_loss(service,sam,"selected peer End after exclusion").await;loss.before_fault(sam);Some(loss)}else{None};service.command(json!({"op":"end"}));if let Some(loss)=selected_end.as_mut(){wait(service,peer,"selected peer canonical End held",20,|v|v["connection"]["state"]=="Ended"&&native_activity(sam)["native_owned_hold"]==true).await;loss.protected(sam);}if let Some(loss)=selected_end{loss.terminal(sam);}running.close();sam.close();checkpoint(root,&format!("new-run-no-start-inheritance-{terminal}-terminal"));
 }
}
