 service.command(json!({"op":"peer"}));let private=service.private();let mut peer=Client::start(&private,&own.join("peer"),None,true,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;let second=bundle(&mut service,&peer).await;let mut sam=Native::start(&peer,None,false);ready_owner(&mut service,&peer,&sam,&second.0,false).await;two_peer_ghost(&mut service,&consumer,&running,&first.0,&peer,&sam,&second.0).await;std::fs::write(sam.root.join("unaffected-check"),b"monitor healthy peer through app offline").unwrap();elapsed(&mut service,1).await;checkpoint(&own,"real-prerequisite-Start-current-two-peer-native-movement");
